/// `…/profile_photo/image.jpg` -> `…/profile_photo/thumbs/image_200x200.jpg`
/// (generated by the image resize extension).
String profileThumbnailLocation(String profilePhotoLocation) =>
    profilePhotoLocation
        .replaceAll('profile_photo', 'profile_photo/thumbs')
        .replaceAll('image', 'image_200x200');
